 if(!hash_equals($csrf,(string)($_POST['csrf']??''))){flash('Phiên làm việc không hợp lệ.','danger');tkb_redirect($tab);}
 $action=(string)($_POST['action']??'');
 if($action==='upload'&&$canSettings){$upload=$_FILES['tkb_file']??null;$start=trim((string)($_POST['start_date']??''));$label=trim((string)($_POST['week_label']??''));if(!$upload||($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK){flash('Hãy chọn file Excel thời khóa biểu.','danger');tkb_redirect('settings');}if(strtolower(pathinfo((string)($upload['name']??''),PATHINFO_EXTENSION))!=='xlsx'){flash('Chỉ hỗ trợ file .xlsx.','danger');tkb_redirect('settings');}if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start)){flash('Hãy chọn ngày bắt đầu tuần.','danger');tkb_redirect('settings');}$result=tkb_import_week((string)$upload['tmp_name'],$label,$start,$teachers,$classes,(string)($user['name']??''));flash($result['message']??(!empty($result['ok'])?'Đã cập nhật thời khóa biểu tuần mới.':'Không nhập được thời khóa biểu.'),!empty($result['ok'])?'success':'danger');tkb_redirect('settings');}
 if($action==='mapping'&&$canSettings){$teacherMap=[];$classMap=[];foreach((array)($_POST['teacher_raw']??[])as$i=>$raw)$teacherMap[(string)$raw]=(string)($_POST['teacher_value'][$i]??'');foreach((array)($_POST['class_raw']??[])as$i=>$raw)$classMap[(string)$raw]=(string)($_POST['class_value'][$i]??'');tkb_save_mapping($teacherMap,$classMap);flash('Đã lưu bảng ghép tên giáo viên và lớp.','success');tkb_redirect('settings');}
 if($action==='substitution_request'){$week=tkb_week_by_id((string)($_POST['week_id']??''))?:tkb_active_week();$date=(string)($_POST['date']??'');$slotKey=(string)($_POST['slot_key']??'');$sub=trim((string)($_POST['substitute_teacher']??''));$absent=trim((string)($_POST['absent_teacher']??''));if($isTeacher)$absent=$selfTeacher;if(!$week||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$slotKey===''||$sub===''||$absent===''){flash('Thiếu dữ liệu đăng ký dạy thay.','danger');tkb_redirect('substitution');}$target=null;foreach(tkb_resolved_slots($week)as$slot)if(tkb_slot_key($slot)===$slotKey&&($slot['teacher']??'')===$absent){$target=$slot;break;}if(!$target){flash('Không tìm thấy tiết cần đăng ký dạy thay.','danger');tkb_redirect('substitution');}if(tkb_teacher_busy($week,$sub,(int)$target['day'],(string)$target['session'],(int)$target['period'],$date)){flash($sub.' đang có lịch ở tiết này.','danger');tkb_redirect('substitution');}$fit=tkb_teacher_fit($sub,$target,$week,$date);$status=$canApprove?'approved':'pending';$row=['date'=>$date,'week_id'=>$week['id'],'slot_key'=>$slotKey,'day'=>(int)$target['day'],'session'=>(string)$target['session'],'period'=>(int)$target['period'],'class'=>(string)($target['class']?:$target['class_raw']),'class_raw'=>(string)($target['class_raw']??''),'subject'=>(string)$target['subject'],'absent_teacher'=>$absent,'substitute_teacher'=>$sub,'fit_labels'=>$fit['labels'],'note'=>trim((string)($_POST['note']??'')),'status'=>$status,'requested_at'=>date('c'),'requested_by'=>(string)($user['name']??$selfTeacher),'updated_at'=>date('c'),'updated_by'=>(string)($user['name']??'')];if($status==='approved'){$row['approved_at']=date('c');$row['approved_by']=(string)($user['name']??'');}tkb_save_substitution($row);flash($status==='approved'?'Đã xác nhận lịch dạy thay.':'Đã gửi đăng ký dạy thay, chờ Tổ trưởng chuyên môn hoặc Quản trị duyệt.','success');tkb_redirect('substitution');}
