function tkb_lookup_slots(array $week,array $slots,string $mode,string $teacher,string $class):array{$out=[];foreach($slots as$s){$resolvedClass=(string)($s['class']?:$s['class_raw']);$include=$mode==='school'||($mode==='class'&&$class!==''&&$resolvedClass===$class)||($mode==='teacher'&&$teacher!==''&&($s['teacher']??'')===$teacher);if(!$include)continue;$s['_sub']=tkb_substitution_for_slot($week,$s);$s['_sub_role']='';if($mode==='teacher'&&$s['_sub']&&($s['_sub']['absent_teacher']??'')===$teacher)$s['_sub_role']='absent';$out[]=$s;}if($mode==='teacher'&&$teacher!=='')foreach(tkb_week_substitutions($week,true)as$r)if(($r['substitute_teacher']??'')===$teacher)$out[]=['day'=>(int)$r['day'],'session'=>(string)$r['session'],'period'=>(int)$r['period'],'class'=>(string)$r['class'],'class_raw'=>(string)($r['class_raw']??$r['class']),'subject'=>(string)$r['subject'],'teacher'=>$teacher,'teacher_raw'=>$teacher,'_sub'=>$r,'_sub_role'=>'substitute'];return$out;}
function tkb_matrix(array $slots):array{$grid=[];$max=['Sáng'=>4,'Chiều'=>4];foreach($slots as$s){$session=mb_stripos((string)$s['session'],'chiều',0,'UTF-8')!==false?'Chiều':'Sáng';$period=(int)$s['period'];$max[$session]=max($max[$session]??0,$period);$grid[$session][$period][(int)$s['day']][]=$s;}return[$grid,$max];}
function tkb_cell_html(array $items,string $mode):string{if(!$items)return'';$parts=[];foreach($items as$s){$class=(string)($s['class']?:$s['class_raw']);$teacher=(string)($s['teacher']?:$s['teacher_raw']);$small=[];if($mode==='teacher')$small[]='<span class="tkb-class-mini">'.e($class).'</span>';elseif($mode!=='school')$small[]='<span class="tkb-teacher-mini">'.e($teacher).'</span>';$sub=$s['_sub']??null;$role=$s['_sub_role']??'';if($sub){if($role==='substitute')$small[]='<span class="tkb-sub-note">Dạy thay cho '.e((string)$sub['absent_teacher']).'</span>';elseif($role==='absent')$small[]='<span class="tkb-sub-note">Nghỉ · '.e((string)$sub['substitute_teacher']).' dạy thay</span>';else$small[]='<span class="tkb-sub-note">Dạy thay: '.e((string)$sub['substitute_teacher']).'</span>';}if($mode==='school')$small[]='<span class="tkb-class-mini">'.e($class).' · '.e($teacher).'</span>';$parts[]='<div class="tkb-cell-item"><div class="tkb-subject">'.e((string)$s['subject']).'</div>'.implode('',$small).'</div>';}return implode('<div class="tkb-cell-sep"></div>',$parts);}
function tkb_render_matrix(array $slots,string $mode,string $title=''):void{[$grid,$max]=tkb_matrix($slots);if($title!=='')echo'<h5 class="tkb-matrix-title">'.e($title).'</h5>';echo'<div class="tkb-matrix-wrap"><table class="tkb-matrix"><thead><tr><th class="session-col">Buổi</th><th class="period-col">Tiết</th>';for($d=2;$d<=7;$d++)echo'<th>Thứ '.$d.'</th>';echo'</tr></thead><tbody>';foreach(['Sáng','Chiều']as$session){$count=max(1,(int)($max[$session]??4));for($p=1;$p<=$count;$p++){echo'<tr>';if($p===1)echo'<th class="session-name" rowspan="'.$count.'">'.($session==='Sáng'?'S':'C').'</th>';echo'<th class="period-no">'.$p.'</th>';for($d=2;$d<=7;$d++)echo'<td>'.tkb_cell_html((array)($grid[$session][$p][$d]??[]),$mode).'</td>';echo'</tr>';}}echo'</tbody></table></div>';}
