m btn-success"><?=$canApprove?'Xác nhận':'Đăng ký'?></button></form></td><td><?php if($saved):$st=tkb_substitution_status($saved);?><span class="status-<?=e($st)?>"><?=$st==='approved'?'Đã duyệt':($st==='rejected'?'Từ chối':'Chờ duyệt')?></span><?php else:?><span class="text-muted">Chưa đăng ký</span><?php endif;?></td></tr><?php endforeach;if(!$absentSlots):?><tr><td colspan="6" class="text-center text-muted py-3">Không có tiết dạy trong ngày đã chọn.</td></tr><?php endif;?></tbody></table></div><?php endif;?>
