<?php $approvedToday=array_values(array_filter($subRows,fn($r)=>tkb_substitution_status($r)==='approved'));if($approvedToday):?><div class="tkb-card p-3"><h5 class="mb-2">Lịch dạy thay đã duyệt ngày <?=e(date('d/m/Y',strtotime($subDate)))?></h5><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Tiết</th><th>Lớp</th><th>Môn</th><th>GV nghỉ</th><th>GV dạy thay</th></tr></thead><tbody><?php foreach($approvedToday as$r):?><tr><td><?=e($r['session'])?> · <?=e($r['period'])?></td><td><?=e($r['class'])?></td><td><?=e($r['subject'])?></td><td><?=e($r['absent_teacher'])?></td><td><strong class="text-success"><?=e($r['substitute_teacher'])?></strong></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
